mapper.select:
SELECT TRUNC(CLOSED_DATE) AS CLOSED_DATE, UPDATED_AT, ADMIN_ID
  FROM TBL_CLOSED_DAY
 WHERE CLOSED_DATE >= #{from}
   AND CLOSED_DATE < #{to}
 ORDER BY CLOSED_DATE

SELECT TRUNC(MOVE_DATE) AS MOVE_DAY, COUNT(*) AS CNT
  FROM TBL_RESERVATION
 WHERE STATUS = '01'
   AND MOVE_DATE >= #{from}
   AND MOVE_DATE < #{to}
 GROUP BY TRUNC(MOVE_DATE)
